            if 1 in seq and len(seq) > 1:
                palette_row = r
                break
    if palette_row is None:
        return g

    seq = [v for v in g[palette_row] if v != 0]

    # The source design is the 8-connected component of color 1 outside the strip.
    cells = {(y, x) for y in range(h) for x in range(w)
             if g[y][x] == 1 and not palette_row <= y <= palette_row + 2}
    if not cells:
        return g
    start = next(iter(cells))
    shape = {start}
    stack = [start]
    while stack:
        y, x = stack.pop()
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                p = (y + dy, x + dx)
                if p in cells and p not in shape:
                    shape.add(p)
                    stack.append(p)

    top = min(y for y, x in shape)
    left = min(x for y, x in shape)
    height = max(y for y, x in shape) - top + 1
    mask = [(y - top, x - left) for y, x in shape]

    # Remove the palette and stack copies in the listed color order,
    # with the existing color-1 copy retaining its position.
    for y in range(palette_row, palette_row + 3):
        for x in range(w):
            if g[y][x] != 0:
                g[y][x] = 0

    i1 = seq.index(1)
    for i, color in enumerate(seq):
        y0 = top + (i - i1) * height
        for dy, dx in mask:
            y, x = y0 + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
